export const css = ":root { --fg: #1b1f24; --muted: #59636e; --bg: #fff; --line: #d1d9e0; --soft: #f6f8fa; --accent: #0969da; --bad: #cf222e; --warn: #9a6700; --good: #1a7f37; color-scheme: light dark; }\n@media (prefers-color-scheme: dark) { :root { --fg: #e6edf3; --muted: #9198a1; --bg: #0d1117; --line: #3d444d; --soft: #151b23; --accent: #4493f8; --bad: #f85149; --warn: #d29922; --good: #3fb950; } }\n* { box-sizing: border-box; }\nbody { margin: 0; font: 14px/1.5 system-ui, -apple-system, \"Segoe UI\", sans-serif; color: var(--fg); background: var(--bg); }\nmain { max-width: 1100px; margin: 0 auto; padding: 0 16px 48px; }\nheader { display: flex; gap: 16px; align-items: center; padding: 12px 0; border-bottom: 1px solid var(--line); margin-bottom: 16px; }\nheader nav { display: flex; gap: 12px; flex: 1; }\na { color: var(--accent); }\nh2 { margin: 20px 0 8px; font-size: 18px; } h3 { margin: 20px 0 6px; font-size: 15px; } h4 { margin: 12px 0 4px; font-size: 13px; color: var(--muted); }\ntable { border-collapse: collapse; width: 100%; display: block; overflow-x: auto; }\nth, td { text-align: left; padding: 6px 10px 6px 0; border-bottom: 1px solid var(--line); vertical-align: top; white-space: nowrap; }\nth { font-weight: 600; color: var(--muted); }\ndl { display: grid; grid-template-columns: max-content 1fr; gap: 4px 16px; margin: 8px 0; } dt { color: var(--muted); } dd { margin: 0; overflow-wrap: anywhere; }\npre { background: var(--soft); border: 1px solid var(--line); border-radius: 6px; padding: 8px; overflow-x: auto; margin: 4px 0; }\ncode { font: 12px ui-monospace, SFMono-Regular, Menlo, monospace; overflow-wrap: anywhere; }\nform, .oc-actions { display: flex; flex-wrap: wrap; gap: 8px; align-items: center; margin: 8px 0; }\ninput, select, button { font: inherit; padding: 4px 8px; border: 1px solid var(--line); border-radius: 6px; background: var(--bg); color: var(--fg); }\nbutton { cursor: pointer; background: var(--soft); } button.oc-danger { color: var(--bad); }\n.oc-login { flex-direction: column; align-items: stretch; max-width: 360px; margin: 80px auto; }\n.oc-connect label, .oc-login label { display: flex; flex-direction: column; gap: 4px; }\n.oc-state { padding: 0 6px; border-radius: 10px; border: 1px solid currentColor; font-size: 12px; }\n.oc-active { color: var(--good); } .oc-reauth_required, .oc-pending { color: var(--warn); } .oc-revoked { color: var(--muted); }\n.oc-error { color: var(--bad); } .oc-warn { color: var(--warn); } .oc-hint { color: var(--muted); } .oc-note { color: var(--good); }\n";
